// Shared theme tint for scanline/glitch comparison shaders.
// theme_mode: 0 = axel (pass-through), 1 = green phosphor, 2 = mono white terminal

vec3 apply_theme_tint(vec3 col, int theme_mode, float theme_strength) {
	if (theme_mode == 0 || theme_strength <= 0.001) {
		return col;
	}
	float lum = dot(col, vec3(0.299, 0.587, 0.114));
	vec3 themed = col;
	if (theme_mode == 1) {
		// Pip-Boy-style green phosphor
		themed = vec3(lum * 0.08, lum * 0.92, lum * 0.28);
	} else if (theme_mode == 2) {
		// High-contrast mono white terminal
		float band = smoothstep(0.18, 0.82, lum);
		themed = mix(vec3(0.04), vec3(0.94), band);
	}
	return mix(col, themed, clamp(theme_strength, 0.0, 1.0));
}

shader_type canvas_item;
// Option 1 — CRT TV stack (nofacer / Asset Library CRT inspired).
// Scanlines, curvature, phosphor mask, rolling line, interference noise, subtle glitch.

#include "res://test/visual_style/shaders/theme_post_fx.gdshaderinc"

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform int theme_mode = 0;
uniform float theme_strength : hint_range(0.0, 1.0) = 1.0;
uniform float curvature : hint_range(0.0, 0.25) = 0.09;
uniform float scanline_strength : hint_range(0.0, 0.5) = 0.14;
uniform float mask_strength : hint_range(0.0, 1.0) = 0.32;
uniform float vignette : hint_range(0.0, 1.0) = 0.24;
uniform float chroma : hint_range(0.0, 0.01) = 0.003;
uniform float noise_amount : hint_range(0.0, 0.2) = 0.06;
uniform float interference : hint_range(0.0, 1.0) = 0.18;
uniform float roll_amount : hint_range(0.0, 1.0) = 0.35;
uniform float roll_speed : hint_range(-8.0, 8.0) = 2.4;
uniform float glitch_rate : hint_range(0.0, 12.0) = 4.5;
uniform float glitch_shift : hint_range(0.0, 0.02) = 0.006;

float hash21(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 curve_uv(vec2 uv, float amount) {
	vec2 c = uv - 0.5;
	float r2 = dot(c, c);
	return uv + c * r2 * amount;
}

void fragment() {
	vec2 uv_screen = SCREEN_UV;
	float t = TIME;

	// Occasional horizontal glitch burst
	float burst_id = floor(t * glitch_rate);
	float burst_on = step(0.72, hash21(vec2(burst_id, 1.7)));
	float burst_y = hash21(vec2(burst_id, 9.3));
	float burst_band = burst_on * (1.0 - smoothstep(0.0, 0.035, abs(uv_screen.y - burst_y)));
	vec2 uv = uv_screen;
	uv.x += (hash21(vec2(burst_id, uv_screen.y * 120.0)) - 0.5) * glitch_shift * burst_band;

	uv = curve_uv(uv, curvature);

	vec3 col = vec3(0.0);
	if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
		float off = chroma;
		col.r = texture(screen_texture, uv + vec2(off, 0.0)).r;
		col.g = texture(screen_texture, uv).g;
		col.b = texture(screen_texture, uv - vec2(off, 0.0)).b;

		// Animated scanlines
		float scan = sin((uv.y + t * 0.04) * 820.0) * 0.5 + 0.5;
		col *= 1.0 - scan * scanline_strength;

		// Phosphor shadow mask
		float mask = sin(uv.x * 920.0) * 0.5 + 0.5;
		col = mix(col, col * 0.86, mask * mask_strength);

		// Rolling bright line (old TV roll)
		float roll = fract(uv.y * 0.5 + t * roll_speed * 0.08);
		float roll_line = smoothstep(0.92, 1.0, roll) * roll_amount;
		col += vec3(roll_line * 0.12);

		// Interference + white static grain
		float grain_t = floor(t * 18.0);
		float grain = hash21(uv * 1400.0 + vec2(grain_t, grain_t * 0.37)) - 0.5;
		float interf = sin(uv.y * 180.0 + t * 14.0) * 0.5 + 0.5;
		col += grain * noise_amount;
		col = mix(col, col * (0.85 + interf * 0.15), interference * 0.35);

		vec2 d = uv - 0.5;
		float vig = 1.0 - dot(d, d) * vignette * 4.0;
		col *= vig;
	}

	col = apply_theme_tint(col, theme_mode, theme_strength);
	COLOR = vec4(col, 1.0);
}

shader_type canvas_item;
// Option 2 — VHS glitch burst (Retro VHS Glitch for Godot 4 inspired, MIT).
// Animated scanlines, white noise static, RGB split, slice/wave glitches.

#include "res://test/visual_style/shaders/theme_post_fx.gdshaderinc"

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform int theme_mode = 0;
uniform float theme_strength : hint_range(0.0, 1.0) = 1.0;
uniform float intensity : hint_range(0.0, 1.0) = 0.55;
uniform float glitch_frequency : hint_range(0.1, 10.0) = 2.8;
uniform float scanline_intensity : hint_range(0.0, 1.0) = 0.28;
uniform float noise_intensity : hint_range(0.0, 1.0) = 0.22;
uniform float slice_intensity : hint_range(0.0, 1.0) = 0.42;
uniform float red_displacement : hint_range(0.0, 0.05) = 0.014;
uniform float green_displacement : hint_range(0.0, 0.05) = 0.012;
uniform float blue_displacement : hint_range(0.0, 0.05) = 0.016;
uniform float ghost_intensity : hint_range(0.0, 0.5) = 0.08;

float random(vec2 st) {
	return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

float noise(vec2 st) {
	vec2 i = floor(st);
	vec2 f = fract(st);
	float a = random(i);
	float b = random(i + vec2(1.0, 0.0));
	float c = random(i + vec2(0.0, 1.0));
	float d = random(i + vec2(1.0, 1.0));
	vec2 u = f * f * (3.0 - 2.0 * f);
	return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void fragment() {
	vec2 uv = SCREEN_UV;
	vec3 col = texture(screen_texture, uv).rgb;

	float glitch_time = TIME * glitch_frequency;
	float glitch_noise = noise(vec2(glitch_time, 0.0));
	float glitch_active = step(1.0 - intensity, glitch_noise);

	if (glitch_active > 0.5) {
		float slice_y = random(vec2(glitch_time * 10.0, 0.0));
		if (abs(uv.y - slice_y) < 0.02 * slice_intensity) {
			float slice_offset = (random(vec2(glitch_time * 15.0, 0.0)) - 0.5) * 0.1 * slice_intensity;
			uv.x += slice_offset;
		}
		float vertical_shift = random(vec2(glitch_time * 8.0, 0.0)) * 0.04 * intensity;
		uv.y += vertical_shift;
		float wave = sin(uv.y * 100.0 + glitch_time * 5.0) * 0.012 * intensity;
		uv.x += wave;
		col = texture(screen_texture, uv).rgb;
	}

	float shift = glitch_active;
	col.r = mix(col.r, texture(screen_texture, uv + vec2(red_displacement * shift, 0.0)).r, shift);
	col.g = mix(col.g, texture(screen_texture, uv + vec2(-green_displacement * shift, 0.0)).g, shift);
	col.b = mix(col.b, texture(screen_texture, uv + vec2(blue_displacement * shift, 0.0)).b, shift);

	float scanline = sin(uv.y * 320.0 + glitch_time * 2.0) * 0.5 + 0.5;
	col *= 1.0 - scanline * scanline_intensity;

	// Always-on subtle static; stronger during glitch bursts
	float static_noise = random(uv + floor(TIME * 24.0)) - 0.5;
	col += static_noise * noise_intensity * (0.35 + glitch_active * 0.65);

	if (ghost_intensity > 0.0) {
		vec3 ghost = texture(screen_texture, uv + vec2(0.008, 0.008)).rgb;
		col = mix(col, ghost, ghost_intensity * 0.45 * (0.5 + glitch_active * 0.5));
	}

	col = apply_theme_tint(col, theme_mode, theme_strength);
	COLOR = vec4(col, 1.0);
}

shader_type canvas_item;
// Option 3 — Terminal CRT (luminance-preserving scanlines + phosphor + static).
// Best dark-scene readability; occasional tracking-line glitches.

#include "res://test/visual_style/shaders/theme_post_fx.gdshaderinc"

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform int theme_mode = 0;
uniform float theme_strength : hint_range(0.0, 1.0) = 1.0;
uniform float curvature : hint_range(0.0, 0.2) = 0.05;
uniform float scan_strength : hint_range(0.0, 0.35) = 0.11;
uniform float phosphor : hint_range(0.0, 1.0) = 0.28;
uniform float noise_strength : hint_range(0.0, 0.15) = 0.045;
uniform float tracking_rate : hint_range(0.0, 8.0) = 3.2;
uniform float tracking_shift : hint_range(0.0, 0.015) = 0.004;

float hash21(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 curve_uv(vec2 uv, float amount) {
	vec2 c = uv - 0.5;
	return uv + c * dot(c, c) * amount;
}

void fragment() {
	vec2 uv_base = SCREEN_UV;
	float t = TIME;

	// Tracking-line glitch (horizontal band wobble)
	float track_id = floor(t * tracking_rate);
	float track_on = step(0.78, hash21(vec2(track_id, 4.2)));
	float track_y = hash21(vec2(track_id, 17.9));
	float track_mask = track_on * (1.0 - smoothstep(0.0, 0.025, abs(uv_base.y - track_y)));
	vec2 uv = uv_base;
	uv.x += (hash21(vec2(track_id, uv_base.y * 80.0)) - 0.5) * tracking_shift * track_mask;

	uv = curve_uv(uv, curvature);
	vec3 col = texture(screen_texture, uv).rgb;
	float lum = dot(col, vec3(0.299, 0.587, 0.114));

	// Luminance-preserving animated scanlines
	float scan = sin((uv.y + t * 0.03) * 680.0) * 0.5 + 0.5;
	float factor = 1.0 - scan * scan_strength;
	vec3 scaled = col * factor;
	float lum2 = dot(scaled, vec3(0.299, 0.587, 0.114));
	if (lum2 > 0.001) {
		col = scaled * (lum / lum2);
	} else {
		col = scaled;
	}

	// RGB phosphor grille
	vec3 ph = vec3(
		sin(uv.x * 900.0) * 0.5 + 0.5,
		sin(uv.x * 900.0 + 2.094) * 0.5 + 0.5,
		sin(uv.x * 900.0 + 4.188) * 0.5 + 0.5
	);
	col = mix(col, col * ph, phosphor * 0.32);

	// Frame-stepped white noise (Pip-Boy terminal snow)
	float grain_t = floor(t * 20.0);
	float grain = hash21(uv * 1100.0 + vec2(grain_t, grain_t * 0.51)) - 0.5;
	col += grain * noise_strength;

	// Soft vignette
	vec2 d = uv - 0.5;
	col *= 1.0 - dot(d, d) * 0.35;

	col = apply_theme_tint(col, theme_mode, theme_strength);
	COLOR = vec4(col, 1.0);
}

